def _parse_ts(ts: str | None) -> float | None:
    """Handle both Z and +00:00 suffixes."""
    if not ts:
        return None
    normalized_ts = ts.rstrip("Z")
    if not normalized_ts.endswith(("+00:00", "-00:00")):
        normalized_ts += "+00:00"
    return datetime.fromisoformat(normalized_ts).timestamp()

