import random

def retry_api_call(func, max_attempts=3):
    for attempt in range(max_attempts):
        try:
            return func()
        except RateLimitError:
            delay = (2 ** attempt) + random.uniform(0, 1)
            time.sleep(delay)
        except Exception as e:
            raise

