from typing import Dict, List, Optional, Callable, Any
from pydantic import BaseModel, Field
from dataclasses import dataclass
import json

class ToolParameter(BaseModel):
    """Tool parameter definition."""
    name: str
    type: str  # "string", "number", "boolean", "object", "array"
    description: str
    required: bool = True
    default: Optional[Any] = None
    enum: Optional[List[Any]] = None

class Tool(BaseModel):
    """Tool definition."""
    name: str = Field(..., pattern=r"^[a-zA-Z0-9_-]+$")
    description: str
    parameters: List[ToolParameter] = Field(default_factory=list)
    version: str = "1.0.0"
    tags: List[str] = Field(default_factory=list)

    def to_json_schema(self) -> dict:
        """Convert tool parameters to JSON Schema."""
        properties = {}
        required = []

        for param in self.parameters:
            properties[param.name] = {
                "type": param.type,
                "description": param.description
            }
            if param.enum:
                properties[param.name]["enum"] = param.enum
            if param.default is not None:
                properties[param.name]["default"] = param.default
            if param.required:
                required.append(param.name)

        return {
            "type": "object",
            "properties": properties,
            "required": required
        }

class ToolRegistry:
    """Registry for MCP tools."""

    def __init__(self):
        self._tools: Dict[str, Tool] = {}
        self._handlers: Dict[str, Callable] = {}

    def register(
        self,
        tool: Tool,
        handler: Optional[Callable] = None
    ) -> None:
        """
        Register a tool.

        Args:
            tool: Tool definition
            handler: Optional handler function

        Raises:
            ValueError: If tool name already registered
        """
        if tool.name in self._tools:
            raise ValueError(f"Tool '{tool.name}' already registered")

        self._tools[tool.name] = tool
        if handler:
            self._handlers[tool.name] = handler

    def unregister(self, name: str) -> None:
        """Unregister a tool."""
        self._tools.pop(name, None)
        self._handlers.pop(name, None)

    def get_tool(self, name: str) -> Optional[Tool]:
        """Get tool by name."""
        return self._tools.get(name)

    def list_tools(self, tags: Optional[List[str]] = None) -> List[Tool]:
        """
        List all registered tools.

        Args:
            tags: Optional tag filter

        Returns:
            List of tools (filtered by tags if provided)
        """
        tools = list(self._tools.values())

        if tags:
            tools = [
                tool for tool in tools
                if any(tag in tool.tags for tag in tags)
            ]

        return tools

    def get_handler(self, name: str) -> Optional[Callable]:
        """Get tool handler function."""
        return self._handlers.get(name)

    def execute(self, name: str, **params) -> Any:
        """
        Execute a tool.

        Args:
            name: Tool name
            **params: Tool parameters

        Returns:
            Tool execution result

        Raises:
            ValueError: If tool not found or no handler
        """
        tool = self.get_tool(name)
        if not tool:
            raise ValueError(f"Tool '{name}' not found")

        handler = self.get_handler(name)
        if not handler:
            raise ValueError(f"No handler for tool '{name}'")

        # Validate parameters against schema
        schema = tool.to_json_schema()
        # ... validation logic here ...

        return handler(**params)

