def predict_with_retry(data, max_retries=3):
    for attempt in range(max_retries):
        response = requests.post(
            json=data
        )
        if response.status_code == 429:
            # Exponential backoff
            time.sleep(2 ** attempt)
            continue
        return response.json()
    raise Exception("Rate limit exceeded")

