    # Fix: Retry invalidation with sleep
    max_attempts = 3
    for attempt in range(max_attempts):
        result = cache.invalidate("key1")
        if result:
            break
        if attempt < max_attempts - 1:
            time.sleep(0.05)  # 50ms backoff

    assert result is True

