class SecureRequest(BaseModel):
    user_id: str
    action: str
    parameters: dict

    @validator('user_id')
    def validate_user_id(cls, v):
        """Sanitize user ID."""
        if not v.isalnum():
            raise ValueError('user_id must be alphanumeric')
        if len(v) > 50:
            raise ValueError('user_id too long')
        return v

    @validator('action')
    def validate_action(cls, v):
        """Validate action against whitelist."""
        allowed = ['read', 'write', 'update', 'delete']
        if v not in allowed:
            raise ValueError(f'action must be one of {allowed}')
        return v

@app.post("/api/execute")
async def execute_action(
    request: SecureRequest,
    api_key: str = Header(..., alias="X-API-Key"),
    dry_run: bool = False
):
    """Execute action with security safeguards."""
    # Validate API key
    if not validate_api_key(api_key):
        raise HTTPException(status_code=401, detail="Invalid API key")

    # Audit log
    log_security_event(
        "api_request",
        user=request.user_id,
        action=request.action,
        dry_run=dry_run
    )

    # Dry-run mode
    if dry_run:
        return {
            "executed": False,
            "would_perform": request.action,
            "parameters": request.parameters
        }

    # Execute with safeguards
    try:
        result = execute_with_timeout(
