    core = data['resources']['core']

    remaining_pct = (core['remaining'] / core['limit']) * 100

    if remaining_pct < 25:
        print(f"⚠️ Rate limit critical: {remaining_pct:.1f}% remaining")
    elif remaining_pct < 50:
        print(f"⚠️ Rate limit warning: {remaining_pct:.1f}% remaining")

    return core

